 *     row has such a block or when n <= 0
 *
 * Example: on a board whose row A has only seats 2 and 4 free,
 *   findBlock(1) is "A:2-2" and findBlock(2) skips row A entirely.
 */
class SeatRow {

    private final String label;
    private final boolean[] taken;

    SeatRow(String label, int seats) {
        this.label = label;
        this.taken = new boolean[Math.max(0, seats)];
    }

    String label() {
        return label;
    }

    int size() {
        return taken.length;
    }

    boolean isTaken(int seat) {
        if (seat < 1 || seat > taken.length) {
            return true;
        }
        return taken[seat - 1];
    }

    boolean take(int seat) {
        if (isTaken(seat)) {
            return false;
        }
        taken[seat - 1] = true;
        return true;
    }

    boolean release(int seat) {
        if (seat < 1 || seat > taken.length || !taken[seat - 1]) {
            return false;
        }
        taken[seat - 1] = false;
        return true;
    }

    int freeCount() {
        int free = 0;
        for (boolean seat : taken) {
            if (!seat) {
                free++;
            }
        }
        return free;
    }
}

