    }

    int size() {
        return taken.length;
    }

    boolean isTaken(int seat) {
        if (seat < 1 || seat > taken.length) {
            return true;
        }
        return taken[seat - 1];
    }

    boolean take(int seat) {
        if (isTaken(seat)) {
            return false;
        }
        taken[seat - 1] = true;
        return true;
    }

    boolean release(int seat) {
        if (seat < 1 || seat > taken.length || !taken[seat - 1]) {
