public class SeatBookingBoard {

    private final List<SeatRow> rows = new ArrayList<>();

    public void addRow(String label, int seats) {
        rows.add(new SeatRow(label, seats));
    }

    public int rowCount() {
        return rows.size();
    }

    private SeatRow rowNamed(String label) {
        for (SeatRow row : rows) {
            if (row.label().equals(label)) {
                return row;
            }
        }
        return null;
    }

    public boolean book(String label, int seat) {
        SeatRow row = rowNamed(label);
        if (row == null) {
            return false;
        }
        return row.take(seat);
    }

    public boolean cancel(String label, int seat) {
        SeatRow row = rowNamed(label);
        if (row == null) {
            return false;
        }
        return row.release(seat);
    }

    public int freeSeats() {
        int free = 0;
        for (SeatRow row : rows) {
            free = free + row.freeCount();
        }
        return free;
    }

    public String findBlock(int n) {
        if (n <= 0) {
            return null;
        }
        for (SeatRow row : rows) {
            int run = 0;
            for (int seat = 1; seat <= row.size(); seat++) {
                if (row.isTaken(seat)) {
                    run = 0;
                } else {
                    run++;
                    if (run == n) {
                        int first = seat - n + 1;
                        return row.label() + ":" + first + "-" + seat;
                    }
                }
            }
        }
        return null;
    }
}
